WebLink.url:
var asset = '{!User.Asset_Class__c}';
var assetFieldID = '{!$Setup.Application_Settings_Hierarchy__c.ActivityAssetClass_fieldID__c}';


// Id necesarios porque el botón se usara para crear Activities desde todos ellos
var accountId = '{!Account.Id}';
var contactId = '{!Contact.Id}';
var campaignId = '{!Campaign.Id}';
var opportunityId = '{!Opportunity.Id}';
var prospectId = '{!Lead.Id}';

var params = '&retURL=%2F';

if (campaignId != ''){
	params += campaignId + '&what_id=' + campaignId;
}else if (opportunityId != ''){
	params += opportunityId + '&what_id=' + opportunityId + '&who_id=' + accountId;
}else if (contactId != ''){
	params += contactId + '&who_id=' + contactId;
}else if (prospectId != ''){
	params += prospectId + '&who_id=' + prospectId;
}else {
	params += accountId + '&what_id=' + accountId;
}

if(asset != ''){
	var a = asset.split(';');
	if(a.length==1){
		params += '&' + assetFieldID + '=' + a[0];
	}
}

window.parent.location.assign('/00T/e?' + params);
